package io.rift.cronos;
public class WorkspacePolicyHarness {
 static int count;static void ok(boolean v){count++;if(!v)throw new AssertionError();}interface Op{void run();}static void bad(Op op){try{op.run();}catch(IllegalArgumentException e){count++;return;}throw new AssertionError();}
 public static void main(String[] args){ok(WorkspacePolicy.account("25:device").equals("25:device"));ok(WorkspacePolicy.account("25:0x"+"a".repeat(40)).startsWith("25:"));for(String a:new String[]{"1:device","25:0x"+"A".repeat(40),"25:device/other","",null})bad(()->WorkspacePolicy.account(a));for(String op:new String[]{"list","save","remove","export","import"})ok(WorkspacePolicy.operation(op).equals(op));for(String op:new String[]{"clear","rpc","sign","credentials","file",null})bad(()->WorkspacePolicy.operation(op));ok(WorkspacePolicy.id("12345678-1234-1234-1234-123456789abc").length()==36);bad(()->WorkspacePolicy.id("../../file"));ok(JsonBudget.check("{\"value\":\"[{]}\\\"\"}",1024,2).length()>0);bad(()->JsonBudget.check("[".repeat(40)+"]".repeat(40),1024,32));bad(()->JsonBudget.check("{\"value\":\""+"🎨".repeat(10)+"\"}",30,2));bad(()->JsonBudget.check("{",30,2));bad(()->JsonBudget.check("}",30,2));System.out.println("Workspace policy assertions passed: "+count);}
}
